<body>
  <main>
    <header>
      <h1>Pocket Garden</h1>
      <p>Keep track of which plants you have put in the ground.</p>
      <p class="note">Your planting choices and filter reset when you reload the page.</p>
    </header>

    <div class="filters" role="group" aria-label="Filter plants by light">
      <button type="button" class="filter-btn" data-filter="all" aria-pressed="true">All plants</button>
      <button type="button" class="filter-btn" data-filter="sun" aria-pressed="false">Loves sun</button>
      <button type="button" class="filter-btn" data-filter="shade" aria-pressed="false">Likes shade</button>
    </div>

    <p class="status" id="status" aria-live="polite"></p>

    <section class="grid" id="grid" aria-label="Plant cards"></section>
  </main>

  <script>
    const PLANTS = [
      {
        id: 'basil',
        name: 'Basil',
        light: 'sun',
        description: 'Warm, sunny spot with at least six hours of direct light. Pinch off flowers to keep the leaves coming.'
      },
      {
        id: 'sunflower',
        name: 'Sunflower',
        light: 'sun',
        description: 'Tall and bright. Give it full sun and room to grow.'
      },
      {
        id: 'mint',
        name: 'Mint',
        light: 'shade',
        description: 'Happiest in partial shade and moist soil. Grow it in a pot to keep it contained.'
      }
    ];

    const LIGHT_LABELS = {
      sun: 'Loves sun',
      shade: 'Likes shade'
    };

    // In-memory state only. Nothing is saved, so everything resets on reload.
    const state = {
      filter: 'all',
      planted: new Set()
    };

    const grid = document.getElementById('grid');
    const statusEl = document.getElementById('status');
    const filterButtons = Array.from(document.querySelectorAll('.filter-btn'));
    const cards = new Map();

    function buildCard(plant) {
      const article = document.createElement('article');
      article.className = 'card';
      article.setAttribute('aria-labelledby', `name-${plant.id}`);

      const heading = document.createElement('h2');
      heading.id = `name-${plant.id}`;
      heading.textContent = plant.name;

      const badge = document.createElement('span');
      badge.className = `badge ${plant.light}`;
      badge.textContent = LIGHT_LABELS[plant.light];

      const desc = document.createElement('p');
      desc.className = 'desc';
      desc.textContent = plant.description;

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'plant-btn';
      btn.setAttribute('aria-pressed', 'false');
      btn.textContent = 'Mark as planted';
      btn.addEventListener('click', () => togglePlanted(plant.id));

      article.append(heading, badge, desc, btn);
      cards.set(plant.id, { article, btn });
      return article;
    }

    function renderPlantState(plantId) {
      const { article, btn } = cards.get(plantId);
      const isPlanted = state.planted.has(plantId);

      btn.textContent = isPlanted ? 'Planted' : 'Mark as planted';
      btn.setAttribute('aria-pressed', String(isPlanted));
      article.classList.toggle('planted', isPlanted);
    }

    function togglePlanted(plantId) {
      if (state.planted.has(plantId)) {
        state.planted.delete(plantId);
      } else {
        state.planted.add(plantId);
      }
      renderPlantState(plantId);
      updateStatus();
    }

    function applyFilter() {
      for (const plant of PLANTS) {
        const { article } = cards.get(plant.id);
        article.hidden = state.filter !== 'all' && plant.light !== state.filter;
      }

      filterButtons.forEach(btn => {
        btn.setAttribute('aria-pressed', String(btn.dataset.filter === state.filter));
      });

      updateStatus();
    }

    function updateStatus() {
      const visibleCount = PLANTS.filter(
        p => state.filter === 'all' || p.light === state.filter
      ).length;

      statusEl.textContent =
        `Showing ${visibleCount} of ${PLANTS.length} plants. ${state.planted.size} planted.`;
    }

    filterButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        state.filter = btn.dataset.filter;
        applyFilter();
      });
    });

    // Initialise
    PLANTS.forEach(plant => grid.appendChild(buildCard(plant)));
    PLANTS.forEach(plant => renderPlantState(plant.id));
    applyFilter();
  </script>
</body>
